import {icon} from './icons.js';
import {frameBuilderDialog} from './frame-builder-ui.js';
import {CATALOG,definition,ports,busy,component,V} from './engine.js';
import {repeatSection,extendRun,rodRun,chainModel,mergeGenerated} from './generators.js';
export function generatorDialog({model,selected,showDialog,commit,openPathBuilder}){
 const $=s=>document.querySelector(s),rods=CATALOG.filter(d=>d.group==='rods'),host=model.parts.find(p=>p.id===selected),free=host?ports(host).filter(p=>['slot','end'].includes(p.kind)&&!busy(model,host.id,p.key)):[];
 showDialog(`<h2>Generate</h2><button id="gen-frame" class="generator-path">${icon('cube')}<span>Grid & frame<small>2D grids · frames · octagonal towers</small></span><span>↗</span></button><button id="gen-path" class="generator-path"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 19C3 0 21 24 21 5M3 13 8 14M8 8 13 9M14 15 19 16"/></svg><span>Path builder<small>Track · flexi · spline import</small></span><span>↗</span></button><label class="field"><span>Operation</span><select id="gen-kind"><option value="run">Build a rod run</option><option value="extend" ${!free.length?'disabled':''}>Extend the selected part</option><option value="repeat" ${!model.parts.length?'disabled':''}>Repeat a section</option><option value="chain">Create a chain</option></select></label><div id="gen-fields"></div><p id="gen-result" role="status"></p><button id="gen-apply" class="button">Add to model</button><p class="note">Uses fixed K’NEX part lengths. Matching rod ends snap automatically. Each generation is one undo step.</p>`);
 $('#gen-path').onclick=()=>openPathBuilder();
 $('#gen-frame').onclick=()=>frameBuilderDialog({model,showDialog,commit});
 const field=(name,id,value,min=1,max=100,step=1)=>`<label class="field"><span>${name}</span><input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
 const rodselect=`<label class="field"><span>Rod length</span><select id="gen-rod">${rods.map(d=>`<option value="${d.id}" ${d.id==='r-yellow'?'selected':''}>${d.name} · ${d.nominal} mm</option>`).join('')}</select></label>`;
 const origin=()=>{if(!model.parts.length)return [0,30,0];return [Math.max(...model.parts.map(p=>p.pos[0]))+120,30,0];};let next=null;
 function calculate(){try{const kind=$('#gen-kind').value,n=Number($('#gen-count').value);if(kind==='repeat'){const ids=[...document.querySelectorAll('[data-section]:checked')].map(e=>model.parts[Number(e.value)].id);next=repeatSection(model,{ids,copies:n,delta:['x','y','z'].map(a=>Number($('#gen-'+a).value)),angle:Number($('#gen-angle').value)});}else if(kind==='extend')next=extendRun(model,{id:selected,portKey:$('#gen-port').value,segments:n,rod:$('#gen-rod').value});else next=mergeGenerated(model,kind==='chain'?chainModel({count:n,closed:$('#gen-closed').checked,origin:origin()}):rodRun({segments:n,rod:$('#gen-rod').value,origin:origin()}));$('#gen-result').textContent=`Adds ${next.parts.length-model.parts.length} parts and ${next.links.length-model.links.length} connections. Total: ${next.parts.length} parts.`;$('#gen-apply').disabled=false;}catch(e){next=null;$('#gen-result').textContent=e.message;$('#gen-apply').disabled=true;}}
 function fields(){const kind=$('#gen-kind').value;$('#gen-fields').innerHTML=field(kind==='repeat'?'Additional copies':kind==='chain'?'Links':'Rod segments','gen-count',kind==='chain'?16:4,1,kind==='chain'?160:50)+(kind==='run'||kind==='extend'?rodselect:'')+(kind==='extend'?`<label class="field"><span>Open connection on ${definition(host).name}</span><select id="gen-port">${free.map(p=>`<option value="${p.key}">${p.key}</option>`).join('')}</select></label>`:'')+(kind==='chain'?'<label class="joint-lock"><input type="checkbox" id="gen-closed"><span>Close into a loop</span></label><p class="note">Large chain 90987. Pin spacing is estimated at 26 mm from the supplier’s joined-link measurement. Chain geometry is editable; flexible chain dynamics and sprocket drive are not simulated.</p>':'')+(kind==='repeat'?`<div class="axis-grid">${['x','y','z'].map((a,i)=>`<label>${a.toUpperCase()} spacing · mm<input id="gen-${a}" type="number" value="${i?0:150}" step="1"></label>`).join('')}</div>${field('Rotation per copy around Y (degrees)','gen-angle',0,-360,360)}<p class="note">Select the parts that form one section. Connections inside that section are copied.</p><div class="section-list">${model.parts.map((p,i)=>`<label class="joint-lock"><input data-section type="checkbox" value="${i}" ${selected?component(model,selected).has(p.id)?'checked':'':i===0?'checked':''}><span>#${i+1} ${definition(p).name}</span></label>`).join('')}</div>`:'');$('#gen-fields').oninput=calculate;$('#gen-fields').onchange=calculate;calculate();}
 $('#gen-kind').onchange=fields;$('#gen-apply').onclick=()=>{if(!next)return;commit(next);$('#dialog').close();};if(free.length)$('#gen-kind').value='extend';fields();
}
